-- PORTFOLIO-LIFECYCLE-1 (2026-10-18, pillar autonomy; owner directive: the system shall automatically maintain,
-- implement, deploy and upgrade its own portfolio, programs and projects)
--
-- WHY THIS IS DATA AND NOT CODE
-- The audit DB already ships the engines this needs: fleet_crons -> fleet_tasks type='workflow' executes SQL steps on the
-- */10 tick, and the code loop already turns a well-formed agent_issues row into a PR and a deploy. What was missing is the
-- loop that joins them for the portfolio: measured 2026-10-18, qnfo-audit held 1 portfolio, 5 programs, 89 projects, 149 WBS
-- tasks and 555 roadmap items, and:
--   * project_ledger had 3 rows, none of them a deploy, so project_deployments (the view that answers "what does this project
--     run") returned 0 rows while deployment_history held 1577 deploys, 486 of them in the last 7 days for workers that each
--     already have a W.<worker> project;
--   * project_state was empty, so nothing recorded what version a project runs;
--   * 70 active projects had no phase at all, so v_project_health could only answer no_phases;
--   * no step anywhere turned a portfolio gap into implementable work or marked a project upgraded when its owner shipped.
-- The existing hourly jobs maintain the register (PROJ-/UPG- roadmap rows, program health, compat upgrades) but stop at
-- filing; nothing linked a deploy back to the project or drove an upgrade to completion.
--
-- WHAT THIS ADDS (one workflow, hourly at :10, no worker deploy)
--   1. phases: any active project without a phase gets one, so health is measurable.
--   2. deploy -> ledger: every successful deployment_history row in the last 7 days whose resource is a W.<worker> project is
--      linked as project_ledger action='deployed' (idempotent on deploy:<id>), so project_deployments becomes true.
--   3. state: one project_state snapshot per linked deploy, carrying worker + version + deployer.
--   4. freshness: projects.updated_at advances to the newest deploy of its owner, so "stale project" means what it says.
--   5. programs: a program's updated_at advances when any of its projects moved.
--   6. gaps: daily, deduped portfolio_gaps rows for stale-deploy and deploy-unrecorded (a live worker with no deploy record).
--   7. implement: an active project whose owner has not deployed in 30 days files ONE deduped PORTFOLIO-IMPLEMENT-1 issue with a
--      definition of done (merged change + recorded deploy) that the existing code loop can act on; capped at 2 per run.
--   8. record: a live worker with no deploy record files ONE deduped PORTFOLIO-DEPLOY-RECORD-1 issue; capped at 2 per run.
--   9. roadmap: IMP-<project> roadmap rows follow those issues.
--  10. upgrade closes the loop: when a deploy lands after the issue was filed, the close evidence is written and the issue is
--      closed, and the IMP- roadmap row is verified. This is what makes the loop terminate instead of accreting issues.
--
-- EXPECTED FIRST-RUN EFFECT (measured before writing this file)
--   phases +70, ledger +400 linked deploys (capped), project_state +400 (capped), project_deployments 0 -> 29 projects,
--   gaps 1 stale-deploy + 1 deploy-unrecorded (qnfo-code-orchestrator is live with no deploy row), 1 issue (its record gap).
--
-- SAFETY
--   Every step is idempotent (NOT EXISTS / OR IGNORE / INSERT ... ON CONFLICT), the two issue steps are capped at 2 per run,
--   and nothing is deleted. The close step cannot bypass the close gates: it writes issue_triage.close_evidence first, and
--   the existing issue_close_evidence_required trigger still decides.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM fleet_crons WHERE name='portfolio-lifecycle-hourly'; DELETE FROM fleet_tasks WHERE id='portfolio-lifecycle'; DROP INDEX IF EXISTS idx_project_state_proj_session; the panel rows this workflow wrote are ordinary project data (phases, project_ledger, project_state, portfolio_gaps with kind IN ('project-stale-deploy','deploy-unrecorded'), agent_issues with source='portfolio-lifecycle', roadmap_implementation item LIKE 'IMP-%') and are left in place because they are true records, not schema.

-- The state snapshot lookup runs once per linked deploy; without this index the NOT EXISTS reads the whole table.
CREATE INDEX IF NOT EXISTS idx_project_state_proj_session ON project_state(project_code, session_id);

-- The workflow definition is the single source of truth for the hourly run.
INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('portfolio-lifecycle', PORTFOLIO-LIFECYCLE-1: maintain, implement, deploy and upgrade the portfolio/programs/projects, 'workflow', {"steps":[{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO phases (phase_code, project_code, phase_number, name, description, status) SELECT ''P1-''||p.project_code, p.project_code, 1, ''Operate and verify'', ''auto (PORTFOLIO-LIFECYCLE-1): the project had no phase, so v_project_health could not report progress. Done when its owning worker answers /health and its newest linked deploy is younger than 30 days.'', CASE WHEN p.status=''completed'' THEN ''completed'' ELSE ''in_progress'' END FROM projects p WHERE NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=p.project_code)"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO project_ledger (project_id, session_id, phase, task_id, action, evidence, worker_name, timestamp) SELECT p.project_code, ''portfolio-lifecycle'', COALESCE((SELECT MAX(ph.phase_number) FROM phases ph WHERE ph.project_code=p.project_code),1), ''deploy:''||dh.id, ''deployed'', ''version ''||COALESCE(dh.version_id,''?'')||'' deployed by ''||COALESCE(dh.deployed_by,''?''), dh.resource_name, COALESCE(dh.deployed_at, datetime(''now'')) FROM deployment_history dh JOIN projects p ON p.project_code=''W.''||dh.resource_name WHERE dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'' AND replace(substr(COALESCE(dh.deployed_at,''''),1,19),''T'','' '') >= datetime(''now'',''-7 days'') AND NOT EXISTS (SELECT 1 FROM project_ledger l WHERE l.task_id=''deploy:''||dh.id) ORDER BY dh.id DESC LIMIT 400"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO project_state (project_code, session_id, current_phase, phase_progress, resource_counts, git_commit) SELECT l.project_id, l.task_id, l.phase, 1.0, json_object(''worker'', dh.resource_name, ''version'', dh.version_id, ''deployed_at'', dh.deployed_at, ''deployed_by'', dh.deployed_by), NULL FROM project_ledger l JOIN deployment_history dh ON l.task_id=''deploy:''||dh.id WHERE l.action=''deployed'' AND NOT EXISTS (SELECT 1 FROM project_state s WHERE s.project_code=l.project_id AND s.session_id=l.task_id) ORDER BY l.id DESC LIMIT 400"},{"type":"sql","db":"AUDIT","sql":"UPDATE projects SET updated_at = (SELECT MAX(replace(substr(dh.deployed_at,1,19),''T'','' '')) FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'') WHERE EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'' AND replace(substr(dh.deployed_at,1,19),''T'','' '') > COALESCE(projects.updated_at,''''))"},{"type":"sql","db":"AUDIT","sql":"UPDATE programs SET updated_at=datetime(''now'') WHERE program_code IN (SELECT DISTINCT program_code FROM projects WHERE updated_at >= datetime(''now'',''-1 day''))"},{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT ''project-stale-deploy'', p.project_code, ''active project whose owner last deployed ''||COALESCE((SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success''),''never''), date(''now'') FROM projects p WHERE p.status=''active'' AND p.owner_service IS NOT NULL AND COALESCE((SELECT MAX(replace(substr(dh.deployed_at,1,19),''T'','' '')) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success''),''1970-01-01'') < datetime(''now'',''-30 days'')"},{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT ''deploy-unrecorded'', s.service, ''live worker ''||s.service||'' has no successful deploy in deployment_history, so its project cannot show what it runs'', date(''now'') FROM service_registry s WHERE s.kind=''worker'' AND s.state=''live'' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=s.service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'')"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''PORTFOLIO-IMPLEMENT-1: ''||p.project_code, ''Filed by portfolio-lifecycle (hourly, automated). Project ''||p.project_code||'' (''||COALESCE(p.name,''?'')||'') is active and its owner '' ||p.owner_service||'' last deployed ''||COALESCE((SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success''),''never'') ||'', older than 30 days.''||char(10)|| ''Definition of done: a merged change in ''||p.github_repo||'' that advances this project, followed by a deploy of ''||p.owner_service|| '' recorded in deployment_history. Evidence: that deployment_history row (id and version).'', ''portfolio-lifecycle'',''maintenance'',''medium'',''open'', CAST(strftime(''%s'',''now'') AS INTEGER)*1000, CAST(strftime(''%s'',''now'') AS INTEGER)*1000 FROM projects p WHERE p.status=''active'' AND p.owner_service IS NOT NULL AND p.github_repo IS NOT NULL AND EXISTS (SELECT 1 FROM deployment_history dh0 WHERE dh0.resource_name=p.owner_service AND dh0.action=''deploy'' AND COALESCE(dh0.status,''success'')=''success'') AND (SELECT MAX(replace(substr(dh.deployed_at,1,19),''T'','' '')) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'') < datetime(''now'',''-30 days'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title=''PORTFOLIO-IMPLEMENT-1: ''||p.project_code AND a.status=''open'') ORDER BY (SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service) ASC LIMIT 2"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''PORTFOLIO-DEPLOY-RECORD-1: ''||s.service, ''Filed by portfolio-lifecycle (hourly, automated). ''||s.service||'' is live but deployment_history has no successful deploy row for it, so its portfolio project cannot show what version it runs or when it last changed.''||char(10)|| ''Definition of done: either its deploys are recorded in deployment_history through the canonical path, or this issue names the path it actually deploys by and project_state is populated from it. Evidence: the deployment_history row, or the mapping note.'', ''portfolio-lifecycle'',''observability'',''medium'',''open'', CAST(strftime(''%s'',''now'') AS INTEGER)*1000, CAST(strftime(''%s'',''now'') AS INTEGER)*1000 FROM service_registry s WHERE s.kind=''worker'' AND s.state=''live'' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=s.service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title=''PORTFOLIO-DEPLOY-RECORD-1: ''||s.service AND a.status=''open'') ORDER BY s.service LIMIT 2"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence, created_at) SELECT ''IMP-''||p.project_code, ''portfolio-lifecycle'', substr(''Implement ''||COALESCE(p.name,p.project_code),1,200), ''project'', p.project_code, ''open'', ''auto: implementation requested by PORTFOLIO-IMPLEMENT-1 #''||a.id, datetime(''now'') FROM projects p JOIN agent_issues a ON a.title=''PORTFOLIO-IMPLEMENT-1: ''||p.project_code AND a.status=''open'' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation r WHERE r.item=''IMP-''||p.project_code)"},{"type":"sql","db":"AUDIT","sql":"UPDATE issue_triage SET close_evidence=''auto (PORTFOLIO-LIFECYCLE-1): a deploy landed for the project owner after this issue was filed, see deployment_history'' WHERE issue_id IN (SELECT a.id FROM agent_issues a JOIN projects p ON a.title=''PORTFOLIO-IMPLEMENT-1: ''||p.project_code WHERE a.status=''open'' AND EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'' AND CAST(strftime(''%s'', replace(substr(dh.deployed_at,1,19),''T'','' '')) AS INTEGER)*1000 > a.created_at))"},{"type":"sql","db":"AUDIT","sql":"UPDATE agent_issues SET status=''closed'', updated_at=CAST(strftime(''%s'',''now'') AS INTEGER)*1000 WHERE status=''open'' AND title LIKE ''PORTFOLIO-IMPLEMENT-1: %'' AND id IN (SELECT t.issue_id FROM issue_triage t WHERE t.close_evidence LIKE ''auto (PORTFOLIO-LIFECYCLE-1)%'')"},{"type":"sql","db":"AUDIT","sql":"UPDATE roadmap_implementation SET status=''verified'', verified_at=datetime(''now''), evidence=''auto: the implementation issue closed after a deploy'' WHERE item LIKE ''IMP-%'' AND status<>''verified'' AND EXISTS (SELECT 1 FROM agent_issues a JOIN projects p ON a.title=''PORTFOLIO-IMPLEMENT-1: ''||p.project_code WHERE ''IMP-''||p.project_code=roadmap_implementation.item AND a.status=''closed'')"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO cloud_ops_events (id, ts, kind, text, meta, job, status) SELECT ''portfolio-lifecycle-''||strftime(''%Y%m%d%H'',''now''), datetime(''now''), ''portfolio-lifecycle'', ''PORTFOLIO-LIFECYCLE-1: ''||(SELECT COUNT(*) FROM project_ledger WHERE action=''deployed'')||'' linked deploys over '' ||(SELECT COUNT(DISTINCT project_id) FROM project_ledger WHERE action=''deployed'')||'' projects | '' ||(SELECT COUNT(*) FROM projects WHERE status=''active'' AND NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=projects.project_code))||'' active projects without a phase | '' ||(SELECT COUNT(*) FROM agent_issues WHERE source=''portfolio-lifecycle'' AND status=''open'')||'' open portfolio issues'', NULL, ''portfolio-lifecycle'', ''ok''"}]}, 120000, 1, 1, 1, datetime('now'));

-- next_fire NULL = due on the very next tick (fleet-exec: next_fire IS NULL OR next_fire <= now), so the first run happens
-- within a minute of the merge and the dispatcher then writes its own next_fire.
INSERT INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('portfolio-lifecycle-hourly', '10 * * * *', 'portfolio-lifecycle', 1, 'UTC', datetime('now'))
ON CONFLICT(name) DO UPDATE SET cron_expr=excluded.cron_expr, task_id=excluded.task_id, enabled=excluded.enabled, updated_at=excluded.updated_at;

-- First-run backfill. Each statement is the same one the workflow runs every hour, so this is not a special case:
-- applying the file makes the portfolio true now, and the cron keeps it true.
INSERT OR IGNORE INTO phases (phase_code, project_code, phase_number, name, description, status) SELECT 'P1-'||p.project_code, p.project_code, 1, 'Operate and verify', 'auto (PORTFOLIO-LIFECYCLE-1): the project had no phase, so v_project_health could not report progress. Done when its owning worker answers /health and its newest linked deploy is younger than 30 days.', CASE WHEN p.status='completed' THEN 'completed' ELSE 'in_progress' END FROM projects p WHERE NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=p.project_code);
INSERT INTO project_ledger (project_id, session_id, phase, task_id, action, evidence, worker_name, timestamp) SELECT p.project_code, 'portfolio-lifecycle', COALESCE((SELECT MAX(ph.phase_number) FROM phases ph WHERE ph.project_code=p.project_code),1), 'deploy:'||dh.id, 'deployed', 'version '||COALESCE(dh.version_id,'?')||' deployed by '||COALESCE(dh.deployed_by,'?'), dh.resource_name, COALESCE(dh.deployed_at, datetime('now')) FROM deployment_history dh JOIN projects p ON p.project_code='W.'||dh.resource_name WHERE dh.action='deploy' AND COALESCE(dh.status,'success')='success' AND replace(substr(COALESCE(dh.deployed_at,''),1,19),'T',' ') >= datetime('now','-7 days') AND NOT EXISTS (SELECT 1 FROM project_ledger l WHERE l.task_id='deploy:'||dh.id) ORDER BY dh.id DESC LIMIT 400;
INSERT INTO project_state (project_code, session_id, current_phase, phase_progress, resource_counts, git_commit) SELECT l.project_id, l.task_id, l.phase, 1.0, json_object('worker', dh.resource_name, 'version', dh.version_id, 'deployed_at', dh.deployed_at, 'deployed_by', dh.deployed_by), NULL FROM project_ledger l JOIN deployment_history dh ON l.task_id='deploy:'||dh.id WHERE l.action='deployed' AND NOT EXISTS (SELECT 1 FROM project_state s WHERE s.project_code=l.project_id AND s.session_id=l.task_id) ORDER BY l.id DESC LIMIT 400;
UPDATE projects SET updated_at = (SELECT MAX(replace(substr(dh.deployed_at,1,19),'T',' ')) FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success') WHERE EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success' AND replace(substr(dh.deployed_at,1,19),'T',' ') > COALESCE(projects.updated_at,''));
UPDATE programs SET updated_at=datetime('now') WHERE program_code IN (SELECT DISTINCT program_code FROM projects WHERE updated_at >= datetime('now','-1 day'));
INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT 'project-stale-deploy', p.project_code, 'active project whose owner last deployed '||COALESCE((SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success'),'never'), date('now') FROM projects p WHERE p.status='active' AND p.owner_service IS NOT NULL AND COALESCE((SELECT MAX(replace(substr(dh.deployed_at,1,19),'T',' ')) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success'),'1970-01-01') < datetime('now','-30 days');
INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT 'deploy-unrecorded', s.service, 'live worker '||s.service||' has no successful deploy in deployment_history, so its project cannot show what it runs', date('now') FROM service_registry s WHERE s.kind='worker' AND s.state='live' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=s.service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success');
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT 'PORTFOLIO-IMPLEMENT-1: '||p.project_code, 'Filed by portfolio-lifecycle (hourly, automated). Project '||p.project_code||' ('||COALESCE(p.name,'?')||') is active and its owner ' ||p.owner_service||' last deployed '||COALESCE((SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success'),'never') ||', older than 30 days.'||char(10)|| 'Definition of done: a merged change in '||p.github_repo||' that advances this project, followed by a deploy of '||p.owner_service|| ' recorded in deployment_history. Evidence: that deployment_history row (id and version).', 'portfolio-lifecycle','maintenance','medium','open', CAST(strftime('%s','now') AS INTEGER)*1000, CAST(strftime('%s','now') AS INTEGER)*1000 FROM projects p WHERE p.status='active' AND p.owner_service IS NOT NULL AND p.github_repo IS NOT NULL AND EXISTS (SELECT 1 FROM deployment_history dh0 WHERE dh0.resource_name=p.owner_service AND dh0.action='deploy' AND COALESCE(dh0.status,'success')='success') AND (SELECT MAX(replace(substr(dh.deployed_at,1,19),'T',' ')) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success') < datetime('now','-30 days') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title='PORTFOLIO-IMPLEMENT-1: '||p.project_code AND a.status='open') ORDER BY (SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service) ASC LIMIT 2;
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT 'PORTFOLIO-DEPLOY-RECORD-1: '||s.service, 'Filed by portfolio-lifecycle (hourly, automated). '||s.service||' is live but deployment_history has no successful deploy row for it, so its portfolio project cannot show what version it runs or when it last changed.'||char(10)|| 'Definition of done: either its deploys are recorded in deployment_history through the canonical path, or this issue names the path it actually deploys by and project_state is populated from it. Evidence: the deployment_history row, or the mapping note.', 'portfolio-lifecycle','observability','medium','open', CAST(strftime('%s','now') AS INTEGER)*1000, CAST(strftime('%s','now') AS INTEGER)*1000 FROM service_registry s WHERE s.kind='worker' AND s.state='live' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=s.service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.title='PORTFOLIO-DEPLOY-RECORD-1: '||s.service AND a.status='open') ORDER BY s.service LIMIT 2;
INSERT INTO roadmap_implementation (item, source, title, artifact_type, artifact_ref, status, evidence, created_at) SELECT 'IMP-'||p.project_code, 'portfolio-lifecycle', substr('Implement '||COALESCE(p.name,p.project_code),1,200), 'project', p.project_code, 'open', 'auto: implementation requested by PORTFOLIO-IMPLEMENT-1 #'||a.id, datetime('now') FROM projects p JOIN agent_issues a ON a.title='PORTFOLIO-IMPLEMENT-1: '||p.project_code AND a.status='open' WHERE NOT EXISTS (SELECT 1 FROM roadmap_implementation r WHERE r.item='IMP-'||p.project_code);
UPDATE issue_triage SET close_evidence='auto (PORTFOLIO-LIFECYCLE-1): a deploy landed for the project owner after this issue was filed, see deployment_history' WHERE issue_id IN (SELECT a.id FROM agent_issues a JOIN projects p ON a.title='PORTFOLIO-IMPLEMENT-1: '||p.project_code WHERE a.status='open' AND EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action='deploy' AND COALESCE(dh.status,'success')='success' AND CAST(strftime('%s', replace(substr(dh.deployed_at,1,19),'T',' ')) AS INTEGER)*1000 > a.created_at));
UPDATE agent_issues SET status='closed', updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE status='open' AND title LIKE 'PORTFOLIO-IMPLEMENT-1: %' AND id IN (SELECT t.issue_id FROM issue_triage t WHERE t.close_evidence LIKE 'auto (PORTFOLIO-LIFECYCLE-1)%');
UPDATE roadmap_implementation SET status='verified', verified_at=datetime('now'), evidence='auto: the implementation issue closed after a deploy' WHERE item LIKE 'IMP-%' AND status<>'verified' AND EXISTS (SELECT 1 FROM agent_issues a JOIN projects p ON a.title='PORTFOLIO-IMPLEMENT-1: '||p.project_code WHERE 'IMP-'||p.project_code=roadmap_implementation.item AND a.status='closed');
INSERT INTO cloud_ops_events (id, ts, kind, text, meta, job, status) SELECT 'portfolio-lifecycle-'||strftime('%Y%m%d%H','now'), datetime('now'), 'portfolio-lifecycle', 'PORTFOLIO-LIFECYCLE-1: '||(SELECT COUNT(*) FROM project_ledger WHERE action='deployed')||' linked deploys over ' ||(SELECT COUNT(DISTINCT project_id) FROM project_ledger WHERE action='deployed')||' projects | ' ||(SELECT COUNT(*) FROM projects WHERE status='active' AND NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=projects.project_code))||' active projects without a phase | ' ||(SELECT COUNT(*) FROM agent_issues WHERE source='portfolio-lifecycle' AND status='open')||' open portfolio issues', NULL, 'portfolio-lifecycle', 'ok';
